    for c in range(W): colsets.append([r for r in range(H) if I[r][c]==0])
    for r in range(H): rowsets.append([c for c in range(W) if I[r][c]==0])
    # full columns/rows (periodic stripes are full; noise cells incomplete)
    fullcols={c for c,cs in enumerate(colsets) if len(cs)==H}
